78	pub trait ValueIndexer {
79	    type ValueType;
80	
81	    /// Add multiple values associated with a single point
82	    /// This function should be called only once for each point
83	    fn add_many(
84	        &mut self,
85	        id: PointOffsetType,
86	        values: Vec<Self::ValueType>,
87	        hw_counter: &HardwareCounterCell,
88	    ) -> OperationResult<()>;
89	
90	    /// Extract index-able value from payload `Value`
91	    fn get_value(value: &Value) -> Option<Self::ValueType>;
92	
93	    /// Try to extract index-able values from payload `Value`, even if it is an array
94	    fn get_values(value: &Value) -> Vec<Self::ValueType> {
95	        match value {
96	            Value::Array(values) => values.iter().filter_map(|x| Self::get_value(x)).collect(),
97	            _ => Self::get_value(value).map(|x| vec![x]).unwrap_or_default(),
98	        }
99	    }
100	
101	    /// Add point with payload to index
102	    fn add_point(
103	        &mut self,
104	        id: PointOffsetType,
105	        payload: &[&Value],
106	        hw_counter: &HardwareCounterCell,
107	    ) -> OperationResult<()> {
108	        self.remove_point(id)?;
109	        let mut flatten_values: Vec<_> = vec![];
110	        for value in payload.iter() {
111	            match value {
112	                Value::Array(values) => {
113	                    flatten_values.extend(values.iter().filter_map(|x| Self::get_value(x)));
114	                }
115	                _ => {
116	                    if let Some(x) = Self::get_value(value) {
117	                        flatten_values.push(x);
118	                    }
119	                }
120	            }
121	        }
122	        self.add_many(id, flatten_values, hw_counter)
123	    }
124	
125	    /// remove a point from the index
126	    fn remove_point(&mut self, id: PointOffsetType) -> OperationResult<()>;
127	}
